"""PEFT LoRA helpers for Qwen3-ASR (-hf adapters)."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_lora")

# Catalog id for the official 1.7B-hf base used by known JA anime LoRAs.
DEFAULT_LORA_BASE_ID = "qwen3-asr-1.7b"
_DEFAULT_LORA_BASE_HUB = "Qwen/Qwen3-ASR-1.7B-hf"


def looks_like_lora_adapter(root: Path | str) -> bool:
    path = Path(root)
    if not path.is_dir():
        return False
    if not (path / "adapter_config.json").is_file():
        return False
    return (
        (path / "adapter_model.safetensors").is_file()
        or (path / "adapter_model.bin").is_file()
    )


def read_adapter_base_hub(adapter_dir: Path | str) -> str:
    path = Path(adapter_dir) / "adapter_config.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return ""
    if not isinstance(data, dict):
        return ""
    return str(
        data.get("base_model_name_or_path")
        or data.get("base_model")
        or ""
    ).strip()


def resolve_lora_base_dir(adapter_dir: Path | str) -> Path:
    """Resolve local base weights for a LoRA adapter directory."""
    from ..download import is_model_installed, model_local_path

    adapter = Path(adapter_dir)
    hub = read_adapter_base_hub(adapter).lower()
    candidates: list[str] = [DEFAULT_LORA_BASE_ID]
    if "0.6" in hub:
        candidates.insert(0, "qwen3-asr-0.6b")
    for mid in candidates:
        if is_model_installed(mid):
            return model_local_path(mid)

    # Sibling fallback when companions were unpacked manually.
    sibling = adapter.parent / DEFAULT_LORA_BASE_ID
    if sibling.is_dir() and (sibling / "config.json").is_file():
        return sibling

    raise RuntimeError(
        f"Qwen3 LoRA at {adapter} needs base weights "
        f"({DEFAULT_LORA_BASE_ID} / {_DEFAULT_LORA_BASE_HUB}). "
        "Download the companion base model from the app library, then retry."
    )


def attach_lora(base_model: Any, adapter_dir: Path | str) -> Any:
    """Wrap ``base_model`` with PEFT adapter weights."""
    try:
        from peft import PeftModel
    except ImportError as err:
        raise RuntimeError(
            "Qwen3 LoRA requires the peft package. "
            "Run ensure-asr-qwen3 / 一键修复, then retry."
        ) from err
    path = Path(adapter_dir)
    _log.info("Attaching Qwen3 LoRA adapter from %s", path)
    model = PeftModel.from_pretrained(base_model, str(path))
    model.eval()
    return model
